-- Read-only checks after create-bimo-drafts.sql. No purchases or user changes.
select jsonb_build_object(
'items',(select jsonb_agg(jsonb_build_object('asset_key',c.asset_key,'slot',c.slot,'name',p.name,'is_active',p.is_active,'is_coming_soon',p.is_coming_soon,'is_released',c.is_released,'cost_byn',p.cost_byn,'coefficient',p.coefficient,'price',greatest(1,round(p.cost_byn*p.coefficient*public.current_crystal_rate())::integer+p.price_adjustment_crystals),'category',cat.slug,'effect',p.effect,'media',p.media,'image_url',p.image_url) order by c.asset_key) from public.bimo_catalog c join public.shop_products p on p.id=c.product_id join public.shop_categories cat on cat.id=p.category_id),
'visible_bimo_count',(select count(*) from public.shop_products p join public.shop_categories c on c.id=p.category_id where p.effect like 'bimo:%' and (p.is_active or p.is_coming_soon) and c.is_active),
'equipment_count',(select count(*) from public.bimo_equipment),
'access',(select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'anon_select',has_table_privilege('anon',c.oid,'SELECT'),'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'authenticated_insert',has_table_privilege('authenticated',c.oid,'INSERT'),'authenticated_update',has_table_privilege('authenticated',c.oid,'UPDATE'),'authenticated_delete',has_table_privilege('authenticated',c.oid,'DELETE'),'service_select',has_table_privilege('service_role',c.oid,'SELECT'),'service_insert',has_table_privilege('service_role',c.oid,'INSERT'),'service_update',has_table_privilege('service_role',c.oid,'UPDATE'),'service_delete',has_table_privilege('service_role',c.oid,'DELETE'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('bimo_catalog','bimo_equipment')),
'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'definition',pg_get_constraintdef(oid))) from pg_constraint where conrelid in ('public.bimo_catalog'::regclass,'public.bimo_equipment'::regclass))
) as verification;
